  VALUES
    (cid,'Machining','CNC machining of flight-critical brackets','R. Alvarez','Aerospace tier-1 customers (68% of revenue)','6 machinists across 2 shifts','5-axis mill MC-104, mill MC-107','MOM/ERP, CAM server','Electricity, compressed air','7075-T6 aluminium billet','Alpine Metals','3 of 5 spindles running',24,12,NULL,'~$38k per lost day; AOG penalties on two contracts','AS9100 traceability must be maintained; requalification after repair','CAM post-processors, calibrated probes, tooling crib','MC-104 5-axis is the only machine able to run the wing-rib family','Outside processing agreement with Cascade Precision (7-day lead)','critical',true,true),
    (cid,'Assembly','Final assembly and kitting','M. Nguyen','All customers','9 assemblers','Torque systems, test bench','MOM/ERP, e-traveler','Electricity, HVAC','Purchased hardware, fasteners','Northline Fasteners','One line at 60% takt',48,24,NULL,'Shipments stop within 2 days of assembly loss','Torque records are a customer requirement','Machining output, incoming inspection','Single calibrated torque verification bench','Manual torque wrenches with paper log, 5-day limit','critical',true,true),
    (cid,'Quality','Inspection and product release','S. Patel','All customers','3 inspectors','CMM-2, calibrated gauges','Quality module, cert archive','Electricity, HVAC (20±2°C)','Gauge standards','Precision Calibration Inc.','CMM plus manual gauging',24,8,NULL,'No release = no shipments, regardless of production','Release without inspection is a regulatory nonconformance','Temperature-controlled lab, calibration status','CMM-2 is the only machine capable of the profile tolerance','Sub-contract inspection at Cascade Precision','critical',true,false),
    (cid,'IT','ERP / MOM availability','D. Brooks','Indirectly all customers','1 IT lead + MSP','Servers, network','ERP, MOM, file server','Electricity, internet','—','Northstar IT (MSP)','Read-only ERP access',12,8,4,'Scheduling, traceability and shipping all stop','Traceability records must be reconstructable','Internet link, backup integrity','Single fibre link to the site','Cellular failover router; paper travelers for 3 days','critical',true,true),
    (cid,'Supply chain','Raw material supply — aluminium billet','T. Okafor','Aerospace customers','2 planners','—','ERP','—','7075-T6, 6061-T6','Alpine Metals','4 weeks of billet on hand',336,168,NULL,'Production halts once buffer is consumed','Alternate mill requires customer source approval','Mill certs, incoming inspection','Alpine Metals is sole approved mill for 7075-T6','Second source (Ridgeline Alloys) qualified for 6061 only','high',true,false),
    (cid,'Logistics','Shipping and receiving','K. Ferris','All customers','3 warehouse staff','Forklift, dock','ERP, carrier portals','Electricity','Packaging','Regional carrier','Manual pick and paper packing list',48,16,NULL,'Finished goods pile up; revenue recognition slips','Shipping documents are part of the certification package','Dock access, carrier availability','Single loading dock','Second carrier account; local courier for AOG','high',true,true),
    (cid,'Maintenance','Preventive and emergency maintenance','J. Whitfield','Indirect','2 technicians','Tool crib, spares','CMMS module','Electricity','Spare parts','OEM service partners','One technician per shift',72,24,NULL,'Equipment recovery time doubles without maintenance capacity','PM records support AS9100 equipment control','Spares availability, OEM support contracts','Only one technician is trained on the 5-axis controller','Contracted OEM field service, 48h response','high',true,false),
