  INSERT INTO public.bcm_risks
    (company_id, risk, category, department, cause, consequence, affected_process, likelihood, impact, existing_controls, preventive_action, recovery_action, owner_name, due_date, status, residual_risk)
  VALUES
    (cid,'Extended power outage (>8 hours)','utilities','Facilities','Regional grid failure or storm damage','All production stops; in-process parts scrapped; ovens lose cycle','All production',3,4,'Utility contract, surge protection','Quote a generator sized for CMM lab, servers and one cell','Prioritised restart sequence; notify customers within 4 hours','J. Whitfield',current_date + 45,'in_progress','Moderate once generator is installed'),
    (cid,'5-axis mill MC-104 catastrophic spindle failure','equipment','Machining','Bearing wear, crash, or coolant contamination','Wing-rib family cannot be produced in-house; 7-day outside processing lead','CNC machining',3,5,'PM programme, vibration checks, spindle spare on order','Hold a rebuilt spindle on site; monthly vibration trending','Outside processing at Cascade Precision; reprioritise order book','R. Alvarez',current_date + 30,'in_progress','High until the spare spindle arrives'),
    (cid,'Ransomware attack on ERP / file server','technology','IT','Phishing, unpatched remote access','ERP, traceability and scheduling unavailable for days','ERP / MOM availability',3,5,'MFA, EDR, nightly off-site backups','Quarterly phishing tests; immutable backup copies; segment the shop network','Isolate, restore from off-site backup, run paper travelers','D. Brooks',current_date + 21,'open','High — recovery has not been fully tested'),
    (cid,'Alpine Metals (sole-source billet) failure','supply_chain','Supply chain','Financial distress, mill allocation or quality escape','Production halts after the 4-week buffer','Raw material supply',2,5,'4-week buffer stock, quarterly supplier review','Qualify Ridgeline Alloys for 7075-T6 with customer source approval','Release buffer, expedite alternate mill, reprioritise by customer criticality','T. Okafor',current_date + 90,'open','High until the second source is approved'),
    (cid,'Fire in the machining cell','facility','Machining','Chip fire, hydraulic leak, electrical fault','Partial facility loss and extended downtime','CNC machining',2,5,'Suppression on the 5-axis, hot-work permit, monthly inspection','Chip management standard; thermal survey of panels','Emergency response, insurance, alternate facility assessment','J. Whitfield',current_date + 60,'open','Moderate with suppression in place'),
    (cid,'Loss of the only 5-axis programmer','people','Engineering','Resignation, illness or injury','New programmes stall; changeovers slow dramatically','CNC machining',3,4,'Documented post-processors, some programmes archived','Cross-train a second programmer; retain a contract programmer','Contract programmer on 48h call; freeze new programme work','R. Alvarez',current_date + 75,'open','Moderate once cross-training is complete'),
    (cid,'CMM-2 failure or loss of calibration','quality','Quality','Mechanical failure, environmental excursion, calibration lapse','Product cannot be released; shipments stop','Inspection and product release',3,4,'Annual calibration, environmental monitoring','Service contract with 24h response; pre-approve a sub-contract inspection house','Sub-contract inspection; quarantine affected product','S. Patel',current_date + 40,'in_progress','Moderate'),
    (cid,'Compressed air system failure','utilities','Facilities','Compressor failure or dryer fault','Machining and assembly stop within minutes','All production',3,3,'PM on compressor, filters changed quarterly','Hold a rental-compressor agreement; second dryer','Rental compressor within 8 hours; run manual assembly tasks','J. Whitfield',current_date + 30,'open','Low once rental agreement signed'),
    (cid,'Earthquake causing structural damage','facility','Site','Regional seismic event','Facility unavailable; equipment misaligned','All production',2,5,'Seismic anchoring of racking; insurance','Anchor the CMM and mills; annual walkdown','Facility loss plan; alternate facility assessment; customer communication','L. Moreau',current_date + 120,'open','High — inherent'),
    (cid,'Single fibre internet link failure','technology','IT','Cable cut or carrier outage','ERP and customer portals unreachable','ERP / MOM availability',4,3,'Cellular failover router installed','Test failover monthly; document bandwidth limits','Switch to failover; run paper travelers for shipping','D. Brooks',current_date + 14,'mitigated','Low');
