  INSERT INTO public.bcm_incidents
    (company_id, ref, title, occurred_at, activation_level, incident_commander, location, description, safety_impact, facility_impact, equipment_impact, it_impact, production_impact, supply_chain_impact, customer_impact, immediate_actions, decisions, communications, recovery_actions, final_resolution, lessons_learned, status, recovery_hours, closed_at)
  VALUES
    (cid,'BC-2026-001','Regional power outage — 6 hours', now() - interval '54 days', 2,'J. Whitfield','Whole site','Storm-related substation fault took the site off supply at 13:40 on a Tuesday.','No injuries. Emergency lighting worked; two employees escorted from the CMM lab.','Building dark; HVAC off for 6 hours.','Two in-process parts scrapped when the mills lost position. CMM required re-warm-up.','Servers ran on UPS for 22 minutes then shut down cleanly.','Half a shift lost across both cells; 41 units behind plan.','No impact — no inbound or outbound movements scheduled.','Two shipments slipped by one day; both customers notified the same afternoon.','Accounted for all employees, stopped machines safely, sent non-essential staff home at 15:00.','Ran the second shift on Saturday to recover the schedule rather than expedite outside processing.','Employees by SMS; two customers by phone and email the same day.','Restarted in the pre-agreed sequence: servers, CMM lab HVAC, compressed air, machining.','Full production restored by 08:00 the following day.','No generator meant the CMM lab lost temperature control and cost 3 extra hours of warm-up. Generator sizing quote raised as an action.','closed',18, now() - interval '53 days'),
    (cid,'BC-2026-002','MC-104 spindle bearing failure', now() - interval '17 days', 1,'R. Alvarez','Machining cell','Vibration alarm followed by audible bearing noise during a wing-rib run.','None.','None.','Spindle cartridge failed; machine down 9 days awaiting the rebuild.','None.','Wing-rib family stopped; 3 orders moved to outside processing.','Outside processing capacity consumed at Cascade Precision.','One customer accepted a 5-day slip; one AOG order was expedited at our cost.','Stopped the machine, quarantined the in-process part, called Meridian service.','Approved a $14k expedited spindle rebuild rather than a 4-week standard lead.','Daily status to the two affected customers; internal stand-up each morning.','Outside processing for 3 orders; requalification run and first-article inspection after repair.','Machine back in production; Quality approved restart after FAI.','Vibration trending was not being reviewed monthly — it would have caught this. Monthly trending is now a PM step, and a rebuilt spindle is being held on site.','closed',216, now() - interval '8 days');
  INSERT INTO public.bcm_exercises
    (company_id, title, exercise_type, exercise_date, scenario, objectives, participants, expected_actions, actual_actions, what_worked, what_failed, lessons_learned, next_exercise)
  VALUES
    (cid,'Tabletop — major power outage at 14:00','tabletop', current_date - 70,'A regional outage removes power for 12 hours during peak production.','Test the activation process, decision-making and customer communication.','Site leader, Operations, EHS, Maintenance, Quality, IT, Supply chain','Activate Level 2, account for employees, set restart priorities, notify customers within 4 hours.','Team activated in 12 minutes; restart sequence agreed; customer list took 35 minutes to assemble.','Activation levels and incident command were clear. Restart sequence was agreed and later used for real.','No pre-built customer contact list; nobody owned external communication.','A pre-approved customer contact list and a named communications owner are now part of the plan.', current_date + 20),
    (cid,'Functional — ERP restore from off-site backup','functional', current_date - 30,'ERP server is unrecoverable; restore the latest off-site backup to the cloud instance.','Verify the 8-hour RTO and 4-hour RPO are achievable.','IT lead, Northstar IT, Operations, Quality','Restore within 8 hours with no more than 4 hours of data loss.','Restore completed in 11 hours; data loss was 3 hours.','Backups were valid and complete; RPO met comfortably.','RTO missed by 3 hours — DNS and licence reactivation were not documented.','Document the DNS and licence steps in the recovery runbook and re-test within 90 days.', current_date + 60);
