DO $$
DECLARE
  cid uuid;
  r1 uuid; r2 uuid; r3 uuid;
  i1 uuid; i2 uuid;
  e1 uuid; e2 uuid;
BEGIN
  SELECT id INTO cid FROM public.companies WHERE name ILIKE 'TitanScale%' ORDER BY created_at LIMIT 1;
  IF cid IS NULL THEN RETURN; END IF;

  ALTER TABLE public.bcm_processes DISABLE TRIGGER bcm_processes_template_lock;
  ALTER TABLE public.bcm_risks DISABLE TRIGGER bcm_risks_template_lock;
  ALTER TABLE public.bcm_assets DISABLE TRIGGER bcm_assets_template_lock;
  ALTER TABLE public.bcm_incidents DISABLE TRIGGER bcm_incidents_template_lock;
  ALTER TABLE public.bcm_exercises DISABLE TRIGGER bcm_exercises_template_lock;
  ALTER TABLE public.bcm_actions DISABLE TRIGGER bcm_actions_template_lock;

  DELETE FROM public.bcm_actions WHERE company_id = cid;
  DELETE FROM public.bcm_exercises WHERE company_id = cid;
  DELETE FROM public.bcm_incidents WHERE company_id = cid;
  DELETE FROM public.bcm_assets WHERE company_id = cid;
  DELETE FROM public.bcm_risks WHERE company_id = cid;
  DELETE FROM public.bcm_processes WHERE company_id = cid;





  SELECT id INTO i1 FROM public.bcm_incidents WHERE company_id=cid AND ref='BC-2026-001';
  SELECT id INTO i2 FROM public.bcm_incidents WHERE company_id=cid AND ref='BC-2026-002';


  SELECT id INTO e1 FROM public.bcm_exercises WHERE company_id=cid AND exercise_type='tabletop';
  SELECT id INTO e2 FROM public.bcm_exercises WHERE company_id=cid AND exercise_type='functional';

  SELECT id INTO r1 FROM public.bcm_risks WHERE company_id=cid AND category='technology' AND risk ILIKE 'Ransomware%';
  SELECT id INTO r2 FROM public.bcm_risks WHERE company_id=cid AND risk ILIKE 'Alpine Metals%';
  SELECT id INTO r3 FROM public.bcm_risks WHERE company_id=cid AND risk ILIKE 'Extended power%';


  ALTER TABLE public.bcm_processes ENABLE TRIGGER bcm_processes_template_lock;
  ALTER TABLE public.bcm_risks ENABLE TRIGGER bcm_risks_template_lock;
  ALTER TABLE public.bcm_assets ENABLE TRIGGER bcm_assets_template_lock;
  ALTER TABLE public.bcm_incidents ENABLE TRIGGER bcm_incidents_template_lock;
  ALTER TABLE public.bcm_exercises ENABLE TRIGGER bcm_exercises_template_lock;
  ALTER TABLE public.bcm_actions ENABLE TRIGGER bcm_actions_template_lock;
END $$;